program = '''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != bg}
    if not colors:
        return [row[:] for row in grid]
    fg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    for r0 in range(h - 2):
        for r1 in range(r0 + 2, h):
            if (r1 - r0) % 2:
                continue
            for c0 in range(w - 2):
                for c1 in range(c0 + 2, w):
                    if (c1 - c0) % 2:
                        continue
                    cm = (c0 + c1) // 2
                    # The outlined frame surrounds a missing segment of a vertical line
                    # that enters through its top edge.
                    if r0 == 0 or grid[r0 - 1][cm] != fg:
                        continue
                    if any(grid[r0][c] != fg or grid[r1][c] != fg for c in range(c0, c1 + 1)):
                        continue
                    if any(grid[r][c0] != fg or grid[r][c1] != fg for r in range(r0, r1 + 1)):
                        continue
                    if any(grid[r][cm] != bg for r in range(r0 + 1, r1)):
                        continue
                    for r in range(r0 + 1, r1):
                        out[r][cm] = 4
    return out
'''
